    def dispatch_add_cell(self, y, **kwargs):
        y = int(y)
        if len(self.layout.rows[y].cells) >= ROW_CELL_LIMIT:
            raise ValueError(_("Can't add more than %d cells in one row.") % ROW_CELL_LIMIT)
        if not (0 <= y < len(self.layout.rows)):
