                    )
                ]
        elif self.type == CustomFieldTypeChoices.TYPE_MARKDOWN:
            field = CommentField(widget=SmallTextarea, label=None)
        elif self.type == CustomFieldTypeChoices.TYPE_JSON:
            if simple_json_filter:
