        self.out_headers["Content-Type"] = mime
        for k, zs in list(self.out_headers.items()) + self.out_headerlist:
            response.append("%s: %s" % (k, zs))
        for zs in response:
            m = self.conn.hsrv.ptn_cc.search(zs)
