        """
        Apply food alias automations to passed food
        :param food: unit as string
        :return: food as string (possibly changed by automation)
        """
        if self.ignore_rules:
            return food
        else:
            if self.food_aliases:
                try:
                    return self.food_aliases[food]
                except KeyError:
                    return food
            else:
