class ZopeIterator(Iterator):
    def index(self):
        return super().index()
    def start(self):
        return super().start()
    def end(self):
        return super().end()
    def item(self):
        return super().item()
    def first(self, name=None):
        if self.start:
            return True
        return not self.same_part(name, self._last_item, self.item)
    def last(self, name=None):
        if self.end:
            return True
        return not self.same_part(name, self.item, self._next)
    def same_part(self, name, ob1, ob2):
        if name is None:
            return ob1 == ob2
        no = object()
        return getattr(ob1, name, no) == getattr(ob2, name, no) is not no
    def __next__(self):
        if self._nextIndex > 0:
            self._last_item = self.item
        return super().__next__()
    def next(self):
        if self._nextIndex > 0:
            self._last_item = self.item
