    domain_regex = re.compile("^(?:http\:\/\/|https\:\/\/)([a-zA-Z0-9.-]+)")
    match = ip_regex.findall(url)
    if len(match):
        ip_address = match[0]
        try:
            ipaddress.ip_address(ip_address)
            return ip_address
        except ValueError:
            pass
    match = domain_regex.findall(url)
    if len(match):
        return match[0]
    return None
