def dump_to(
    resource_id: str, fmt: str, offset: int,
    limit: Optional[int], options: dict[str, Any], sort: str,
    search_params: dict[str, Any], user: str
):
    if fmt == 'csv':
        writer_factory = csv_writer
        records_format = 'csv'
    elif fmt == 'tsv':
        writer_factory = tsv_writer
        records_format = 'tsv'
    elif fmt == 'json':
        writer_factory = json_writer
        records_format = 'lists'
    elif fmt == 'xml':
        writer_factory = xml_writer
        records_format = 'objects'
    else:
        assert False, 'Unsupported format'
    bom = options.get('bom', False)
    def start_stream_writer(fields: list[dict[str, Any]]):
        return writer_factory(fields, bom=bom)
    def stream_result_page(offs: int, lim: Union[None, int]):
        return get_action('datastore_search')(
            {'user': user},
            dict({
                'resource_id': resource_id,
                'limit': PAGINATE_BY
                if limit is None else min(PAGINATE_BY, lim),
                'offset': offs,
                'sort': sort,
                'records_format': records_format,
                'include_total': False,
            }, **search_params)
        )
    def stream_dump(offset: int, limit: Union[None, int],
                    paginate_by: int, result: dict[str, Any]):
        with start_stream_writer(result['fields']) as writer:
            while True:
                if limit is not None and limit <= 0:
                    break
                records = result['records']
                yield writer.write_records(records)
                if records_format == 'objects' or records_format == 'lists':
                    if len(records) < paginate_by:
                        break
                elif not records:
                    break
                offset += paginate_by
                if limit is not None:
                    limit -= paginate_by
                    if limit <= 0:
                        break
                result = stream_result_page(offset, limit)
            yield writer.end_file()
    result = stream_result_page(offset, limit)
    if result['limit'] != limit:
        paginate_by = result['limit']
    else:
        paginate_by = PAGINATE_BY
    return stream_dump(offset, limit, paginate_by, result)
class Option(SectionMixin, Generic[T]):
    def _parse_validators(self) -> list[Validator]:
        """Turn the string with validators into the list of functions.
        """
        return _validators_from_string(self.get_validators())
def _validators_from_string(s: str) -> list[Validator]:
    """
    convert a schema validators string to a list of validators
    e.g. "if_empty_same_as(name) unicode_safe" becomes:
    [if_empty_same_as("name"), unicode_safe]
    """
    import ast
    from ckan.logic import get_validator
    out = []
    parts = s.split()
    for p in parts:
        if '(' in p and p[-1] == ')':
            name, args = p.split('(', 1)
            args = args[:-1]
            try:
                parsed_args = ast.literal_eval(args)
                if not isinstance(parsed_args, tuple) or not parsed_args:
                    parsed_args = (parsed_args,)
            except (ValueError, TypeError, SyntaxError, MemoryError):
                parsed_args = args.split(',')
            factory = cast(ValidatorFactory, get_validator(name))
            v = factory(*parsed_args)
        else:
            v = get_validator(p)
        out.append(v)
    return out
